1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		// dir 是打开时确定的绝对路径。即使传入相对目录，也在 Open 时按当时的
23		// 工作目录解析并固定下来：此后调用方切换进程工作目录，本对象的读取与
24		// 保存仍指向最初打开的位置，绝不会按新工作目录重新解释这个相对路径。
25		dir      string
26		lockFile *os.File
27		mu       sync.Mutex
28		state    *persistedState
29	}
30	
31	// Open 打开（或首次使用）位于 dir 的台账。
32	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
33	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
34	// 时按损坏处理；已有台账文件无法读取、解析，存在两条配方编号与版本号
35	// 完全相同的配方记录，存在两条批次编号完全相同的批次记录，
36	// 任一配方版本的任一物料每份克数不是正数，
37	// 任一配方版本内同一物料编号出现多次，
38	// 任一批次绑定的配方版本未登记，
39	// 任一批次的状态不是精确的 "draft"、"executing"、"closed" 之一
40	// （缺失、为空、null、其他字符串，或大小写、前后空格与合法值不同），
41	// 任一批次的计划份数不是正整数，或按其绑定的配方版本计算时某物料的
42	// 应投量（每份克数 × 计划份数）无法精确表示到千分之一克或超过
43	// 9223372036854775.807 克，
44	// 任一批次仍为草稿状态却带有投料记录，
45	// 任一批次已保存投料的登记序号与记录在列表中的位置不一致
46	// （第一条不为 1、零或负数、重号、漏号、跳号，或调换记录位置后
47	// 未同步序号；不同物料共用批次序号、不同批次各自从 1 开始），
48	// 已保存投料的物料编号不属于该批次绑定的配方版本，
49	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
50	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
51	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
52	//
53	// dir 可以是相对目录：其位置只按 Open 调用时的工作目录解析一次并固定。
54	// 打开之后即使进程切换了工作目录，本对象的查询与保存仍始终指向最初打开
55	// 的目录，不会按新工作目录重新解释相对路径；台账操作本身也不会改变调用
56	// 方的工作目录。切换工作目录后另行 Open 同一相对目录，得到的是绑定新位
57	// 置的独立对象，与此前的对象互不影响。
58	func Open(dir string) (*Store, error) {
59		if dir == "" {
60			return nil, errors.New("数据位置不能为空")
61		}
62		// 先按“打开那一刻”的工作目录把位置解析成绝对路径并固定。后续每次
63		// 查询与写入都会重新读取台账文件，若仍持有相对路径，调用方一旦切换
64		// 工作目录，相对路径就会指向别处——可能把已登记批次查成不存在，或把
65		// 变更读写到另一个同名台账。解析为绝对路径后，本对象始终绑定最初打
66		// 开的位置。filepath.Abs 只做词法解析、不访问文件系统，目录尚不存在
67		// （首次使用会自动创建）时也能得到稳定结果。
68		absDir, err := filepath.Abs(dir)
69		if err != nil {
70			return nil, fmt.Errorf("解析数据位置 %q 失败: %w", dir, err)
71		}
72		if err := os.MkdirAll(absDir, 0o755); err != nil {
73			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", absDir, err)
74		}
75		info, err := os.Stat(absDir)
76		if err != nil {
77			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", absDir, err)
78		}
79		if !info.IsDir() {
80			return nil, fmt.Errorf("数据位置 %q 不是目录", absDir)
81		}
82	
83		lockPath := filepath.Join(absDir, lockFileName)
84		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
85		if err != nil {
86			return nil, fmt.Errorf("打开锁文件失败: %w", err)
87		}
88	
89		s := &Store{dir: absDir, lockFile: lf}
90		if err := s.load(); err != nil {
91			lf.Close()
92			return nil, err
93		}
94		return s, nil
95	}
96	
97	// Close 释放台账占用的文件锁。
98	func (s *Store) Close() error {
99		s.mu.Lock()
100		defer s.mu.Unlock()
101		if s.lockFile == nil {
102			return nil
103		}
104		err := s.lockFile.Close()
105		s.lockFile = nil
106		return err
107	}
108	
109	func (s *Store) lockExclusive() error {
110		if s.lockFile == nil {
111			return errors.New("台账已关闭")
112		}
113		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
114			return fmt.Errorf("锁定台账失败: %w", err)
115		}
116		return nil
117	}
118	
119	func (s *Store) lockShared() error {
120		if s.lockFile == nil {
121			return errors.New("台账已关闭")
122		}
123		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
124			return fmt.Errorf("锁定台账失败: %w", err)
125		}
126		return nil
127	}
128	
129	func (s *Store) unlock() {
130		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
131	}
132	
133	func (s *Store) load() error {
134		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
135		if err != nil {
136			if os.IsNotExist(err) {
137				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
138				return nil
139			}
140			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
141		}
142		if len(data) == 0 {
143			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
144			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
145			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
146			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
147		}
148		var st persistedState
149		if err := json.Unmarshal(data, &st); err != nil {
150			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
151		}
152		if st.Version != stateVersion {
153			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
154		}
155		if err := validateState(&st); err != nil {
156			return err
157		}
158		if st.Requests == nil {
159			st.Requests = map[string]*requestRecord{}
160		}
161		s.state = &st
162		return nil
163	}
164	
165	// validateState 检查台账的引用完整性与数量合法性：
166	//   - 配方由配方编号与版本号共同识别，同一台账内每组编号+版本号只能
167	//     对应一条配方记录。只要同组出现第二条记录，无论名称、物料、每份克数
168	//     是否相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或
169	//     最后一条、不能合并物料、也不能自行删除一条后继续——重复记录会让
170	//     查询结果与批次的应投依据取决于文件中的排列顺序。重复版本即使尚未
171	//     被任何批次引用也一样拒绝，其他配方与批次完整也不能放行本次读取。
172	//   - 批次由批次编号唯一识别，同一台账内一个编号只能对应一条批次记录。
173	//     同一编号出现第二条记录，无论绑定的配方版本、计划份数、状态是否
174	//     相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或最后
175	//     一条、不能合并投料、不能自动改号或删除一条后继续——重复记录会让
176	//     同一编号查到的配方、投料与数量核对取决于文件中的排列顺序。其他
177	//     批次完整、投料数量吻合，或调用方只想查看另一个正常批次，都不能
178	//     放行本次读取；不同编号的批次绑定同一配方版本不受影响。
179	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
180	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
181	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
182	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
183	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
184	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
185	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
186	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
187	//     不同版本、不同配方各自使用同一物料编号不受影响。
188	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
189	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
190	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
191	//   - 每个已保存批次的计划份数必须为正整数，且按该批次实际绑定的配方版本
192	//     计算，每种物料的应投量（每份克数 × 计划份数）都必须能精确表示到
193	//     千分之一克、且不超过 maxGramsMilli（9223372036854775.807 克）。
194	//     任一批次份数为零或负数，或任一物料的应投量无法精确表示/超出上限，
195	//     整份台账即视为损坏：不区分草稿、执行中还是已关闭，也不取决于本次
196	//     查询哪个批次——不能自动减少份数、改选其他配方版本或删除问题批次，
197	//     即使其他批次完整也不能放行。上限按每种物料分别判断：多种物料的
198	//     应投量相加超过上限不构成非法，单种物料恰好等于上限仍合法。
199	//   - 每个已保存批次的状态必须精确对应 draft、executing、closed 三个
200	//     字符串之一。状态字段缺失、为空或为 null，或保存成 "ready" 等其他
201	//     字符串，整份台账即视为损坏：不做大小写归一化，也不去除前后空格，
202	//     "Draft"、" draft " 与空字符串一样不合法。不能根据该批次有没有投料
203	//     替它猜一个状态、不能补成草稿，也不能删除该批次或跳过它继续返回
204	//     其他批次与配方——状态无法识别时，草稿带投料、状态机准入、查询
205	//     视图等所有依赖状态的规则都无从套用。即使配方版本与计划份数都正常、
206	//     尚未投料或投料数量恰好吻合，也不能放行；其他批次完整或本次只查询
207	//     别的批次、配方同样不能绕过。
208	//   - 草稿批次不能带有任何投料记录：登记投料只允许操作执行中的批次，
209	//     草稿尚未开始执行，出现投料说明保存内容自相矛盾。任一草稿批次包含
210	//     至少一条投料，整份台账即视为损坏——即使这些投料的物料都属于绑定
211	//     版本、克数均为合法正数、累计实投恰好等于应投，也不能接受；不能
212	//     丢弃投料后当作干净草稿，不能把批次自动改为执行中或已关闭，也不
213	//     能替调用方改选配方版本来继续读取。台账里另有正常批次、调用方只
214	//     查询其他配方或批次，都不能绕过这项矛盾。没有投料的草稿不受影响；
215	//     执行中尚未投料、已关闭批次没有投料或仍有欠投超投都属正常。
216	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
217	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
218	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
219	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
220	//   - 每个批次的投料按保存位置共用一条从 1 开始的登记序列：第一条序号
221	//     必须为 1，此后每条依次加 1，且保存序号必须与该记录在列表中的位置
222	//     一致。不同物料的投料共用同一序列、不按物料各自编号；不同批次各自
223	//     从 1 开始。任一条记录的序号为零或负数、与前一条不连续（漏号、
224	//     跳号）、与其他记录重号，或记录调换了位置却未同步序号，整份台账即
225	//     视为损坏：即使物料归属与数量全部合法也不能接受，不能按自带序号或
226	//     投料时间重排、不能补号、不能删除问题记录后继续。投料时间由调用方
227	//     填写、从不参与排序，时间相同或乱序不能作为序号有误的依据。空投料
228	//     列表不构成序号错误，仍按批次状态规则处理。
229	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
230	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
231	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
232	func validateState(st *persistedState) error {
233		// 先按“配方编号 + 版本号”唯一标识遍历全部配方记录：同组出现第二条
234		// 记录即数据损坏，必须先于一切按标识查找的校验拒绝——否则重复记录
235		// 会让 findRecipe 总是返回排在前面的一条，查询结果与批次应投依据都
236		// 取决于文件排列顺序。完全相同的内容也不是合法重复。
237		versions := make(map[recipeKey]bool, len(st.Recipes))
238		for _, r := range st.Recipes {
239			if r == nil {
240				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
241			}
242			key := recipeKey{r.RecipeNo, r.Version}
243			if versions[key] {
244				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方记录重复",
245					ErrCorruptData, r.RecipeNo, r.Version)
246			}
247			versions[key] = true
248		}
249		for _, r := range st.Recipes {
250			seen := make(map[string]bool, len(r.Materials))
251			for _, m := range r.Materials {
252				if seen[m.MaterialNo] {
253					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
254						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
255				}
256				seen[m.MaterialNo] = true
257				if m.GramsMilli <= 0 {
258					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
259						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
260				}
261			}
262		}
263		// 再按批次编号唯一标识遍历全部批次记录：同一编号出现第二条记录即数据
264		// 损坏，必须先于一切按编号查找的校验拒绝——否则 findBatch 总是返回排在
265		// 前面的一条，同一编号查到的配方、投料与数量核对都取决于文件排列顺序。
266		// 两条记录即使绑定不同配方版本、计划份数不同或状态不同也属于重复；
267		// 内容完全一致同样不是合法记录。不能挑第一条或最后一条、不能合并投料、
268		// 也不能自动改号或删除一条后继续。不同批次绑定同一配方版本不受影响。
269		batchNos := make(map[string]bool, len(st.Batches))
270		for _, b := range st.Batches {
271			if b == nil {
272				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
273			}
274			if batchNos[b.BatchNo] {
275				return fmt.Errorf("%w: 批次编号 %q 的批次记录重复", ErrCorruptData, b.BatchNo)
276			}
277			batchNos[b.BatchNo] = true
278		}
279		for _, b := range st.Batches {
280			// 状态必须精确对应 draft、executing、closed 之一，且必须先于一切
281			// 依赖状态语义的校验（草稿带投料、状态机操作、查询视图）判断：
282			// 无法识别的状态没有任何既有规则可以套用。缺失、为空、null、写成
283			// "ready" 等其他字符串，或大小写不同、前后多了空格，都不能自动
284			// 当成某个合法状态——不能按是否已有投料替它猜状态，不能补成草稿，
285			// 也不能删除该批次后继续。只要一个批次状态不合法，整份台账即视为
286			// 损坏：其他批次与配方完整、本次只想查询别的批次或配方，都不能放行。
287			if !isValidBatchStatus(b.Status) {
288				if b.Status == "" {
289					return fmt.Errorf("%w: 批次 %q 的状态为空或缺失，必须是 %q、%q 或 %q 之一",
290						ErrCorruptData, b.BatchNo, StatusDraft, StatusExecuting, StatusClosed)
291				}
292				return fmt.Errorf("%w: 批次 %q 的状态 %q 无法识别，必须精确为 %q、%q 或 %q 之一（大小写或前后空格不同也不合法）",
293					ErrCorruptData, b.BatchNo, b.Status, StatusDraft, StatusExecuting, StatusClosed)
294			}
295			// 草稿尚未开始执行，不能登记投料；已保存的草稿却带着投料，
296			// 说明记录自相矛盾。必须先于配方归属与数量校验拒绝——否则
297			// 这份草稿还能被打开、调整份数或改选配方版本，留下按旧计划
298			// 登记的投料。不能丢弃投料当作干净草稿，不能自动改状态，也
299			// 不能改选版本后继续。
300			if b.Status == StatusDraft && len(b.Feedings) > 0 {
301				return fmt.Errorf("%w: 批次 %q 仍为草稿状态，却存在 %d 条投料记录",
302					ErrCorruptData, b.BatchNo, len(b.Feedings))
303			}
304			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
305			if r == nil {
306				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
307					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
308			}
309			if err := validateBatchPlan(b, r); err != nil {
310				return err
311			}
312			if err := validateFeedings(b, r); err != nil {
313				return err
314			}
315		}
316		return nil
317	}
318	
319	// validateBatchPlan 检查一个已保存批次的计划份数与按绑定配方版本算出的
320	// 应投量。数量规则本身（正份数、千分之一克精度、逐物料上限）统一由
321	// planRequirements 实现，这里只补充“读取已保存批次”场景的错误分类与
322	// 批次编号：份数非正或应投量非法都属于 ErrCorruptData。
323	// 归属以批次实际绑定的版本为准：换用同编号的其他版本或许能算得通，也
324	// 不能作为接受依据。计划数量是否合法与投料无关：尚未投料、实投不足或
325	// 超出应投都不影响。
326	func validateBatchPlan(b *batchRecord, r *recipeRecord) error {
327		if b.PlannedPortions <= 0 {
328			return fmt.Errorf("%w: 批次 %q 的计划份数 %d 不是正整数",
329				ErrCorruptData, b.BatchNo, b.PlannedPortions)
330		}
331		if _, err := planRequirements(r, b.PlannedPortions); err != nil {
332			return fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
333		}
334		return nil
335	}
336	
337	// validatePlanForRecipe 校验创建或调整草稿批次时，给定份数按配方版本逐
338	// 物料计算的应投量都能精确表示到千分之一克且不超过上限。份数本身的正
339	// 整数检查由调用方按各自输入规则完成（调整草稿时份数传 0 表示不改份数，
340	// 走到这里的必是最终采用的正份数）；数量规则统一由 planRequirements
341	// 实现，这里透传其逐物料说明（物料、配方编号、版本、份数），由调用方
342	// 按本次提交包装为 ErrInvalidInput。
343	func validatePlanForRecipe(r *recipeRecord, portions int) error {
344		_, err := planRequirements(r, portions)
345		return err
346	}
347	
348	// validateFeedings 检查一个批次内已保存投料的登记顺序、合法性与配方归属。
349	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
350	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
351	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
352	// 在此拒绝。
353	//
354	// 序号是整个批次共用的一条登记序列：不同物料的投料依次共用这组序号，
355	// 不按物料各自另起编号；不同批次则各自从 1 开始。列表中第 i 条（位置
356	// 从 1 起）的保存序号必须恰好为 i——第一条必须为 1，此后每条加 1。
357	// 零、负数、漏号、重号、跳号，或只调换了记录位置却没有同步序号，都说明
358	// 记录已经失去登记先后次序，整份台账视为损坏，即使物料归属与数量全部
359	// 合法也不能接受。投料时间只由调用方填写、从不参与排序，因此不能用来
360	// 佐证或否定序号：同一时刻登记、后一条时间早于前一条都属正常。该校验
361	// 只读取现有序号与位置，绝不重排、补号或删除任何投料。
362	func validateFeedings(b *batchRecord, r *recipeRecord) error {
363		acc := newFeedingAccumulator()
364		for i, f := range b.Feedings {
365			// 位置 i+1 上的保存序号必须就是 i+1：先于归属与数量校验判断，
366			// 因为一旦序号与位置不符，调用方已经无法按序号区分这是哪一次
367			// 成功登记——按错误的序号继续核对物料与数量没有意义。不能挑
368			// 记录自带的序号当真、不能按投料时间重排，也不能自行补号或
369			// 删除后继续。空投料列表不会进入这里，不构成序号错误。
370			pos := i + 1
371			if f.Seq != pos {
372				return fmt.Errorf("%w: 批次 %q 投料列表第 %d 条记录的登记序号为 %d，应为 %d：登记序号必须从 1 起按保存位置逐条连续加 1，不能为零或负数、重号、漏号、跳号或与位置不符",
373					ErrCorruptData, b.BatchNo, pos, f.Seq, pos)
374			}
375			belongs := false
376			for _, m := range r.Materials {
377				if m.MaterialNo == f.MaterialNo {
378					belongs = true
379					break
380				}
381			}
382			if !belongs {
383				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
384					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
385			}
386			if f.GramsMilli <= 0 {
387				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
388					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
389			}
390			if !acc.add(f.MaterialNo, f.GramsMilli) {
391				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
392					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
393			}
394		}
395		return nil
396	}
397	
398	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
399	func (s *Store) persist(st *persistedState) error {
400		data, err := json.MarshalIndent(st, "", "  ")
401		if err != nil {
402			return err
403		}
404		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
405		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
406		if err != nil {
407			return err
408		}
409		if _, err := f.Write(data); err != nil {
410			f.Close()
411			return err
412		}
413		if err := f.Sync(); err != nil {
414			f.Close()
415			return err
416		}
417		if err := f.Close(); err != nil {
418			return err
419		}
420		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
421			return err
422		}
423		if d, err := os.Open(s.dir); err == nil {
424			_ = d.Sync()
425			_ = d.Close()
426		}
427		return nil
428	}
429	
430	func cloneState(st *persistedState) (*persistedState, error) {
431		data, err := json.Marshal(st)
432		if err != nil {
433			return nil, err
434		}
435		var out persistedState
436		if err := json.Unmarshal(data, &out); err != nil {
437			return nil, err
438		}
439		if out.Requests == nil {
440			out.Requests = map[string]*requestRecord{}
441		}
442		return &out, nil
443	}
444	
445	// write 是所有写入操作的统一入口：
446	//   - reqNo 为空直接报错；
447	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
448	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
449	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
450	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
451	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
452		if reqNo == "" {
453			return errors.New("请求编号不能为空")
454		}
455		s.mu.Lock()
456		defer s.mu.Unlock()
457		if err := s.lockExclusive(); err != nil {
458			return err
459		}
460		defer s.unlock()
461	
462		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
463		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
464		if err := s.load(); err != nil {
465			return err
466		}
467	
468		payloadRaw, err := json.Marshal(payload)
469		if err != nil {
470			return err
471		}
472		payloadStr := string(payloadRaw)
473	
474		if req, ok := s.state.Requests[reqNo]; ok {
475			if req.Op != op || req.Payload != payloadStr {
476				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
477					ErrRequestConflict, reqNo, req.Op, op)
478			}
479			if err := json.Unmarshal(req.Result, out); err != nil {
480				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
481			}
482			return nil
483		}
484	
485		clone, err := cloneState(s.state)
486		if err != nil {
487			return err
488		}
489		result, err := apply(clone)
490		if err != nil {
491			return err
492		}
493		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
494		if err := s.persist(clone); err != nil {
495			return fmt.Errorf("保存台账失败: %w", err)
496		}
497		s.state = clone
498		if err := json.Unmarshal(result, out); err != nil {
499			return fmt.Errorf("解析请求结果失败: %w", err)
500		}
501		return nil
502	}
503	
504	// read 在共享锁下读取当前状态。
505	func (s *Store) read(fn func(*persistedState) error) error {
506		s.mu.Lock()
507		defer s.mu.Unlock()
508		if err := s.lockShared(); err != nil {
509			return err
510		}
511		defer s.unlock()
512		if err := s.load(); err != nil {
513			return err
514		}
515		return fn(s.state)
516	}
517	
518	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
519	
520	func buildRecipeView(r *recipeRecord) *RecipeView {
521		mats := make([]MaterialView, 0, len(r.Materials))
522		for _, m := range r.Materials {
523			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
524		}
525		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
526	}
527	
528	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
529		v := &BatchView{
530			BatchNo:         b.BatchNo,
531			RecipeNo:        r.RecipeNo,
532			RecipeVersion:   r.Version,
533			RecipeName:      r.Name,
534			PlannedPortions: b.PlannedPortions,
535			Status:          b.Status,
536			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
537			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
538		}
539	
540		for _, f := range b.Feedings {
541			v.Feedings = append(v.Feedings, FeedingView{
542				Seq:        f.Seq,
543				MaterialNo: f.MaterialNo,
544				Grams:      f.GramsMilli.String(),
545				Time:       f.Time,
546				Registrar:  f.Registrar,
547			})
548		}
549	
550		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
551		// 这里仍用同一套累计规则防一手整数回绕。
552		acc := newFeedingAccumulator()
553		for _, f := range b.Feedings {
554			if !acc.add(f.MaterialNo, f.GramsMilli) {
555				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
556					ErrCorruptData, b.BatchNo, f.MaterialNo)
557			}
558		}
559	
560		// 数量核对按配方物料逐项列出；应投量统一由 planRequirements 按本批次
561		// 绑定版本与计划份数计算，与创建、调整、读取校验共用同一套规则。
562		// 台账在读取时已通过 validateState 校验，这里仍防一手同一版本内物料
563		// 编号重复，避免返回重复的数量核对项。
564		required, err := planRequirements(r, b.PlannedPortions)
565		if err != nil {
566			return nil, fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
567		}
568		seen := make(map[string]bool, len(required))
569		for _, item := range required {
570			if seen[item.materialNo] {
571				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
572					ErrCorruptData, r.RecipeNo, r.Version, item.materialNo)
573			}
574			seen[item.materialNo] = true
575			act := acc.total(item.materialNo)
576			v.Materials = append(v.Materials, MaterialRequirement{
577				MaterialNo:      item.materialNo,
578				RequiredGrams:   item.requiredGrams.String(),
579				ActualGrams:     act.String(),
580				DifferenceGrams: (act - item.requiredGrams).String(),
581			})
582		}
583		return v, nil
584	}
585	
586	// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
587	type recipeKey struct {
588		recipeNo string
589		version  string
590	}
591	
592	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
593		for _, r := range st.Recipes {
594			if r.RecipeNo == recipeNo && r.Version == version {
595				return r
596			}
597		}
598		return nil
599	}
600	
601	func findBatch(st *persistedState, batchNo string) *batchRecord {
602		for _, b := range st.Batches {
603			if b.BatchNo == batchNo {
604				return b
605			}
606		}
607		return nil
608	}
