1	package release
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	// rawBatchRecord 用原始 JSON 控制 status 字段的写法：
15	// 传 nil 且 omitempty 时字段缺失，传 RawMessage("null") 写成 null，
16	// 从而能模拟“字段缺失/null/空字符串”等 Go 字符串类型无法区分的损坏形态。
17	type rawBatchRecord struct {
18		BatchNo         string          `json:"batchNo"`
19		RecipeNo        string          `json:"recipeNo"`
20		RecipeVersion   string          `json:"recipeVersion"`
21		PlannedPortions int             `json:"plannedPortions"`
22		Status          json.RawMessage `json:"status,omitempty"`
23		Feedings        []feedingRecord `json:"feedings,omitempty"`
24	}
25	
26	type rawState struct {
27		Version int              `json:"version"`
28		Recipes []*recipeRecord  `json:"recipes"`
29		Batches []rawBatchRecord `json:"batches"`
30	}
31	
32	// writeRawStatusState 写入一份配方为 R1/v1、批次 B-bad（2 份）状态由
33	// statusJSON 原样给出（缺失字段传 nil）的台账，返回写入的字节。
34	func writeRawStatusState(t *testing.T, dir string, statusJSON json.RawMessage, feedings []feedingRecord) []byte {
35		t.Helper()
36		st := rawState{
37			Version: stateVersion,
38			Recipes: []*recipeRecord{recipeR1v1()},
39			Batches: []rawBatchRecord{{
40				BatchNo:         "B-bad",
41				RecipeNo:        "R1",
42				RecipeVersion:   "v1",
43				PlannedPortions: 2, // 计划份数完全合法
44				Status:          statusJSON,
45				Feedings:        feedings,
46			}},
47		}
48		data, err := json.MarshalIndent(st, "", "  ")
49		if err != nil {
50			t.Fatalf("序列化台账失败: %v", err)
51		}
52		if err := os.WriteFile(filepath.Join(dir, stateFileName), data, 0o644); err != nil {
53			t.Fatalf("写入台账文件失败: %v", err)
54		}
55		return data
56	}
57	
58	// Open 时已保存批次的状态不是精确的 draft/executing/closed 之一，
59	// 必须返回 ErrCorruptData：其他字符串、大小写不同、前后空格、空字符串、
60	// null、字段缺失都不合法；即使尚未投料或投料数量已经吻合也不能放行。
61	// 错误信息指出问题批次编号与实际读到的状态，状态为空或缺失时明确说明；
62	// 不能报成笼统的“当前状态不允许该操作”；不返回可用对象，不改写原文件。
63	func TestOpenRejectsUnrecognizedBatchStatus(t *testing.T) {
64		// 投料数量与应投吻合（R1/v1 每份 100 克 × 2 份 = 200 克）也不能放行。
65		matched := []feedingRecord{
66			{Seq: 1, MaterialNo: "M1", GramsMilli: 200000, Time: time.Now(), Registrar: "张三"},
67		}
68		cases := []struct {
69			name       string
70			statusJSON json.RawMessage
71			feedings   []feedingRecord
72			empty      bool // 读不到任何状态内容
73			wantShown  string
74		}{
75			{"其他字符串 ready 且未投料", json.RawMessage(`"ready"`), nil, false, "ready"},
76			{"其他字符串 ready 且投料吻合", json.RawMessage(`"ready"`), matched, false, "ready"},
77			{"其他字符串 pending", json.RawMessage(`"pending"`), nil, false, "pending"},
78			{"首字母大写 Draft", json.RawMessage(`"Draft"`), nil, false, "Draft"},
79			{"全大写 DRAFT", json.RawMessage(`"DRAFT"`), nil, false, "DRAFT"},
80			{"前导空格", json.RawMessage(`" draft"`), nil, false, " draft"},
81			{"尾随空格", json.RawMessage(`"closed "`), nil, false, "closed "},
82			{"前后都有空格", json.RawMessage(`" executing "`), nil, false, " executing "},
83			{"空字符串", json.RawMessage(`""`), nil, true, ""},
84			{"null", json.RawMessage(`null`), nil, true, ""},
85			{"字段缺失", nil, nil, true, ""},
86		}
87		for _, tc := range cases {
88			t.Run(tc.name, func(t *testing.T) {
89				dir := t.TempDir()
90				original := writeRawStatusState(t, dir, tc.statusJSON, tc.feedings)
91	
92				s, err := Open(dir)
93				if !errors.Is(err, ErrCorruptData) {
94					t.Fatalf("无法识别的状态应返回 ErrCorruptData，得到 %v", err)
95				}
96				if s != nil {
97					s.Close()
98					t.Fatalf("损坏台账不应返回可用的 Store 对象")
99				}
100				msg := err.Error()
101				if !strings.Contains(msg, "B-bad") {
102					t.Fatalf("错误信息应指出问题批次编号 B-bad，得到 %v", err)
103				}
104				if tc.empty {
105					if !strings.Contains(msg, "为空或缺失") {
106						t.Fatalf("状态无内容时错误信息应明确说明为空或缺失，得到 %v", err)
107					}
108				} else {
109					if !strings.Contains(msg, tc.wantShown) {
110						t.Fatalf("错误信息应包含实际读到的状态 %q，得到 %v", tc.wantShown, err)
111					}
112				}
113				if strings.Contains(msg, "不允许该操作") {
114					t.Fatalf("读取损坏数据不应报成笼统的操作不允许，得到 %v", err)
115				}
116				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
117				if err != nil {
118					t.Fatal(err)
119				}
120				if !bytes.Equal(got, original) {
121					t.Fatalf("拒绝打开不应改动台账文件")
122				}
123			})
124		}
125	}
126	
127	// 一个批次状态非法时整份台账都不能读取：即使其他批次与配方完全正常，
128	// Open 也必须失败，不能跳过问题批次返回其余内容。
129	func TestOpenOneBatchWithBadStatusFailsWholeLedger(t *testing.T) {
130		dir := t.TempDir()
131		st := rawState{
132			Version: stateVersion,
133			Recipes: []*recipeRecord{recipeR1v1()},
134			Batches: []rawBatchRecord{
135				{BatchNo: "B-ok-1", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: json.RawMessage(`"draft"`)},
136				{BatchNo: "B-bad", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 2, Status: json.RawMessage(`"ready"`)},
137				{BatchNo: "B-ok-2", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 3, Status: json.RawMessage(`"closed"`)},
138			},
139		}
140		data, err := json.MarshalIndent(st, "", "  ")
141		if err != nil {
142			t.Fatal(err)
143		}
144		if err := os.WriteFile(filepath.Join(dir, stateFileName), data, 0o644); err != nil {
145			t.Fatal(err)
146		}
147	
148		s, err := Open(dir)
149		if !errors.Is(err, ErrCorruptData) {
150			t.Fatalf("存在状态非法的批次应整体拒绝，得到 %v", err)
151		}
152		if s != nil {
153			s.Close()
154			t.Fatalf("损坏台账不应返回可用的 Store 对象")
155		}
156		if !strings.Contains(err.Error(), "B-bad") {
157			t.Fatalf("错误信息应指出问题批次编号 B-bad，得到 %v", err)
158		}
159	}
160	
161	// 台账打开后保存内容中的批次状态变成非法值：下一次查询或带有效请求编号的
162	// 写入都必须返回 ErrCorruptData，不能继续使用此前读到的正常数据；查询
163	// 正常批次或配方也不能绕过；被拒绝的操作不改文件、不占请求编号；恢复为
164	// 合法状态后原记录继续可用，被拒绝过的编号仍可合法提交。
165	func TestBatchStatusCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
166		cases := []struct {
167			name      string
168			toStatus  BatchStatus
169			wantShown string
170			empty     bool
171		}{
172			{"改成未知字符串 ready", BatchStatus("ready"), "ready", false},
173			{"改成大小写不同", BatchStatus("Draft"), "Draft", false},
174			{"改成带空格", BatchStatus(" closed "), " closed ", false},
175			{"改成空字符串", BatchStatus(""), "为空或缺失", true},
176		}
177		for _, tc := range cases {
178			t.Run(tc.name, func(t *testing.T) {
179				dir := t.TempDir()
180				s, err := Open(dir)
181				if err != nil {
182					t.Fatal(err)
183				}
184				defer s.Close()
185	
186				if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
187					{MaterialNo: "M1", Grams: "100"},
188				}); err != nil {
189					t.Fatal(err)
190				}
191				if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 2); err != nil {
192					t.Fatal(err)
193				}
194				if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 1); err != nil {
195					t.Fatal(err)
196				}
197				if _, err := s.StartBatch("s2", "B2"); err != nil {
198					t.Fatal(err)
199				}
200				fixedTime := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
201				if _, err := s.AddFeeding("feed-ok", "B2", "M1", "5", fixedTime, "张三"); err != nil {
202					t.Fatal(err)
203				}
204	
205				good, err := os.ReadFile(filepath.Join(dir, stateFileName))
206				if err != nil {
207					t.Fatal(err)
208				}
209				var broken persistedState
210				if err := json.Unmarshal(good, &broken); err != nil {
211					t.Fatal(err)
212				}
213				for _, b := range broken.Batches {
214					if b.BatchNo == "B1" {
215						b.Status = tc.toStatus
216					}
217				}
218				badBytes := writeStateFile(t, dir, &broken)
219	
220				// 查询损坏批次：必须报 ErrCorruptData 并指出编号与实际状态。
221				_, err = s.GetBatch("B1")
222				if !errors.Is(err, ErrCorruptData) {
223					t.Fatalf("状态改坏后查询应返回 ErrCorruptData，得到 %v", err)
224				}
225				if !strings.Contains(err.Error(), "B1") || !strings.Contains(err.Error(), tc.wantShown) {
226					t.Fatalf("错误信息应包含批次编号 B1 与实际状态 %q，得到 %v", tc.wantShown, err)
227				}
228				// 查询正常批次、配方同样失败。
229				if _, err := s.GetBatch("B2"); !errors.Is(err, ErrCorruptData) {
230					t.Fatalf("整份台账损坏后查询正常批次也应失败，得到 %v", err)
231				}
232				if _, err := s.GetRecipe("R1", "v1"); !errors.Is(err, ErrCorruptData) {
233					t.Fatalf("整份台账损坏后查询配方也应失败，得到 %v", err)
234				}
235				// 带有效（从未使用的）请求编号的写入不能绕过。
236				if _, err := s.UpdateDraftBatch("u-rejected", "B1", "", "", 5); !errors.Is(err, ErrCorruptData) {
237					t.Fatalf("损坏台账上调整草稿应返回 ErrCorruptData，得到 %v", err)
238				}
239				if _, err := s.StartBatch("start-rejected", "B1"); !errors.Is(err, ErrCorruptData) {
240					t.Fatalf("损坏台账上开始执行应返回 ErrCorruptData，得到 %v", err)
241				}
242				if _, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "李四"); !errors.Is(err, ErrCorruptData) {
243					t.Fatalf("损坏台账上投料应返回 ErrCorruptData，得到 %v", err)
244				}
245				if _, err := s.RegisterRecipe("r-rejected", "R3", "v1", "新配方", []MaterialInput{
246					{MaterialNo: "M1", Grams: "1"},
247				}); !errors.Is(err, ErrCorruptData) {
248					t.Fatalf("损坏台账上登记配方应返回 ErrCorruptData，得到 %v", err)
249				}
250	
251				// 被拒绝的操作不改文件、不留请求记录。
252				after, err := os.ReadFile(filepath.Join(dir, stateFileName))
253				if err != nil {
254					t.Fatal(err)
255				}
256				if !bytes.Equal(after, badBytes) {
257					t.Fatalf("被拒绝的写入不应改动台账文件")
258				}
259				for _, no := range []string{"u-rejected", "start-rejected", "feed-rejected", "r-rejected"} {
260					if bytes.Contains(after, []byte(no)) {
261						t.Fatalf("被拒绝的写入不应留下请求记录 %q", no)
262					}
263				}
264	
265				// 恢复合法状态后原记录完整可用；被拒绝过的编号仍可合法提交。
266				if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
267					t.Fatal(err)
268				}
269				b1, err := s.GetBatch("B1")
270				if err != nil {
271					t.Fatalf("恢复后查询 B1 应成功: %v", err)
272				}
273				if b1.Status != StatusDraft || b1.PlannedPortions != 2 || len(b1.Feedings) != 0 {
274					t.Fatalf("B1 原有状态与计划应保留: %+v", b1)
275				}
276				adjusted, err := s.UpdateDraftBatch("u-rejected", "B1", "", "", 5)
277				if err != nil {
278					t.Fatalf("被拒绝过的调整编号应仍可合法使用: %v", err)
279				}
280				if adjusted.PlannedPortions != 5 {
281					t.Fatalf("调整结果不正确: %+v", adjusted)
282				}
283				if _, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "李四"); err != nil {
284					t.Fatalf("被拒绝过的投料编号应仍可合法使用: %v", err)
285				}
286				b2, err := s.GetBatch("B2")
287				if err != nil {
288					t.Fatal(err)
289				}
290				if len(b2.Feedings) != 2 {
291					t.Fatalf("恢复后 B2 应保留原投料并能追加，得到 %d 条", len(b2.Feedings))
292				}
293			})
294		}
295	}
296	
297	// 三种合法状态仍按原规则读取：草稿只能在无投料时存在，执行中可以尚未
298	// 投料，已关闭可以没有投料或存在欠投、超投——状态检查不夹带数量吻合
299	// 要求，合法批次不应被这次修正拒绝。
300	func TestExactValidStatusesStillAccepted(t *testing.T) {
301		dir := t.TempDir()
302		fixedTime := time.Date(2026, 10, 2, 9, 0, 0, 0, time.UTC)
303		writeBatchState(t, dir,
304			&batchRecord{BatchNo: "B-draft", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 2, Status: StatusDraft},
305			&batchRecord{BatchNo: "B-exec-empty", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: StatusExecuting},
306			&batchRecord{BatchNo: "B-closed-empty", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: StatusClosed},
307			&batchRecord{BatchNo: "B-closed-under", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: StatusClosed,
308				Feedings: []feedingRecord{{Seq: 1, MaterialNo: "M1", GramsMilli: 40000, Time: fixedTime, Registrar: "张三"}}},
309			&batchRecord{BatchNo: "B-closed-over", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: StatusClosed,
310				Feedings: []feedingRecord{{Seq: 1, MaterialNo: "M1", GramsMilli: 150000, Time: fixedTime, Registrar: "张三"}}},
311		)
312	
313		s, err := Open(dir)
314		if err != nil {
315			t.Fatalf("全部状态合法的台账应正常打开: %v", err)
316		}
317		defer s.Close()
318		for _, no := range []string{"B-draft", "B-exec-empty", "B-closed-empty", "B-closed-under", "B-closed-over"} {
319			if _, err := s.GetBatch(no); err != nil {
320				t.Fatalf("合法批次 %q 应可查询: %v", no, err)
321			}
322		}
323		// 关闭后的投料保护不变。
324		if _, err := s.AddFeeding("f-closed", "B-closed-over", "M1", "1", time.Now(), "张三"); !errors.Is(err, ErrInvalidState) {
325			t.Fatalf("关闭后投料仍应返回 ErrInvalidState，得到 %v", err)
326		}
327		// 无投料草稿仍可调整，执行中仍可投料。
328		if _, err := s.UpdateDraftBatch("u1", "B-draft", "", "", 3); err != nil {
329			t.Fatalf("合法草稿应仍可调整: %v", err)
330		}
331		if _, err := s.AddFeeding("f1", "B-exec-empty", "M1", "10", time.Now(), "张三"); err != nil {
332			t.Fatalf("执行中批次应仍可投料: %v", err)
333		}
334	}
